def note_created_or_updated(
    sender: Any, instance: Any, created: Any, **kwargs: Any
) -> None:
    """
    Signal handler for note creation and updates

    Sends notifications when a note is created or updated
    """
    try:
        # Skip private notes
        if instance.is_private:
            return

        # Get the note author
        author = instance.author

        # For family group notes
        if instance.family_group:
            # For new notes
            if created:
                logger.info(
                    f"New family note created: {instance.title} by {author.username}"
                )

                # Notify family members (excluding author)
                family_members = instance.family_group.members.exclude(id=author.id)

                for member in family_members:
                    NotificationService.create_user_action_notification(
                        user=member,
                        title=f"New family note: {instance.title}",
                        message=f"{author.get_full_name() or author.username} added a new note to your family.",
                        source_object=instance,
                        priority="LOW",
                        data={
                            "note_id": str(instance.id),
                            "note_title": instance.title,
                            "action": "created",
                            "deep_link": f"clancal://notes/{instance.id}",
                        },
                    )
                    logger.info(f"Sent note creation notification to {member.username}")

            # For note updates
            else:
                logger.info(
                    f"Family note updated: {instance.title} by {author.username}"
